"""ta netact"""
from taf.ul.trs_e2e_fw.lib.ems.netact.netact_base import NetactBase


class Netact(NetactBase):
    """ta netact"""
    def __init__(self):
        super(Netact, self).__init__()

    def collect_nodes_data(self, **kwargs):
        """
        Collects data about NetAct nodes ips and ports required by NetAct libraries and firewall request.

        NOTE:
        Connection to was node is required was_host, was_ssh_user, was_ssh_pass must be passed to Setup TA NetAct KW

        @Param kwargs:
            alias (string) Name of execution context.

        Returns:	NetAct nodes and ports.

        Return type:	dict(string, list)
        """
        alias = kwargs.pop('alias', 'default')
        # return self.netact_factory.ta_netact.collect_nodes_data(alias=alias)
        return self.netact_factory.netact.detect_nodes(alias=alias)
